const curatedPeople: Person[] = Array.from(
  new Map(
    inputs.map((player) => [
      player.name.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, ''),
      {
        personId: player.name.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, ''),
        displayName: player.name,
        fullName: player.name,
        aliases: [],
        nationality: player.nationality,
        primaryRoles: player.roles,
        notes: player.notes,
      } satisfies Person,
    ]),
  ).values(),
)

export const people: Person[] = Array.from(new Map([...ratedPeople, ...curatedPeople, ...importedPeople].map((person) => [person.personId, person])).values())

const personIdByName = new Map(people.map((person) => [person.displayName, person.personId]))

const curatedPlayerContexts: PlayerContext[] = inputs.map((input) => ({
  contextId: input.id,
  personId: personIdByName.get(input.name) ?? input.id,
  displayName: input.name,
  teamType: input.teamType,
  teamName: input.team,
  league: input.league,
  country: input.country,
  competitionContexts: (input.competitions ?? []).map((competition) => ({
    competition,
    team: input.team,
    eraLabel: input.era,
    role: 'impact',
  })),
  startYear: input.start,
  endYear: input.end,
  decade: input.decade,
  eraLabel: input.era,
  eligibleModes: input.modes,
  positions: input.positions,
  primaryPositions: input.primary,
  secondaryPositions: input.positions.filter((position) => !input.primary.includes(position)),
  roleTags: input.roles,
  ratings: ratingFor(input.primary[0], input.overall, input.overrides),
  peakWindow: `${input.start}-${input.end}`,
  dataConfidence: input.confidence ?? 'Medium',
  sourceNotes: baseSourceNotes,
  historicalNotes: input.notes,
}))

function mergeUnique<T>(left: T[], right: T[]): T[] {
  return Array.from(new Set([...left, ...right]))
}

function mergePlayerContext(left: PlayerContext, right: PlayerContext): PlayerContext {
  return {
    ...left,
    eligibleModes: mergeUnique(left.eligibleModes, right.eligibleModes),
    positions: mergeUnique(left.positions, right.positions),
    primaryPositions: mergeUnique(left.primaryPositions, right.primaryPositions),
    secondaryPositions: mergeUnique(left.secondaryPositions, right.secondaryPositions),
    roleTags: mergeUnique(left.roleTags, right.roleTags),
    sourceNotes: mergeUnique(left.sourceNotes, right.sourceNotes),
    competitionContexts: [...left.competitionContexts, ...right.competitionContexts],
    dataConfidence: left.dataConfidence === 'High' || right.dataConfidence === 'High' ? 'High' : left.dataConfidence,
    historicalNotes: left.historicalNotes === right.historicalNotes ? left.historicalNotes : `${left.historicalNotes} ${right.historicalNotes}`,
  }
}

export const playerContexts: PlayerContext[] = Array.from(
  [...ratedPlayerContexts, ...curatedPlayerContexts, ...importedPlayerContexts].reduce((contexts, player) => {
    const existing = contexts.get(player.contextId)
    contexts.set(player.contextId, existing ? mergePlayerContext(existing, player) : player)
    return contexts
  }, new Map<string, PlayerContext>()).values(),
)
